// GetHelpContent returns help content for the OCI resources view (Rule 114)
func (m Model) GetHelpContent() help.Content {
	// Interpolated rather than written out: this view lists what the engine
	// app.container_engine resolved to is holding (§3.67).
	engTitle := theme.ContainerEngineLabel(engine.Current().Name)

	return help.Content{
		Title:       "OCI Resources",
		Description: "This view manages the local OCI resources " + engTitle + " holds: Images (with CVE scanning), Networks, Volumes, and Registries. Use Tab/Shift+Tab to switch between tabs.",
		KeyBindings: []help.KeyBinding{
			{Key: "tab / shift+tab", Description: "Switch between Images, Networks, Volumes, and Registries tabs"},
			{Key: "enter (Images)", Description: "View scan details for the selected image (loads from cache; falls back to scan if not yet scanned)"},
			{Key: "N (Images)", Description: "Launch a container from the selected image"},
			{Key: "S (Images)", Description: "Launch a scan for the selected image"},
			{Key: "G (Images)", Description: "Update the selected image to what its Update column shows — the newer patch tag, or the same tag's new build — then remove the image it replaces. Refused while any container, running or stopped, was created from it; the footer names them"},
			{Key: "A (Images)", Description: "Scan every image. The confirmation carries a checkbox to purge the cached results first — unchecked, only what has never been scanned is scanned"},
			{Key: "A (Images)", Description: "Scan all unscanned images using config defaults"},
			{Key: keymap.Delete, Description: "Delete the selected resource (with confirmation)"},
			{Key: keymap.Prune, Description: "Prune unused resources (with confirmation)"},
			{Key: "enter (Networks)", Description: "Inspect the selected network — shows connected containers with IP and MAC addresses"},
			{Key: "N (Networks)", Description: "Create a new network"},
			{Key: "N (Volumes)", Description: "Create a new volume"},
			{Key: "N (Registries)", Description: "Add a registry"},
			{Key: "E (Registries)", Description: "Edit the selected registry"},
			{Key: "U (Registries)", Description: "Log in or out of the selected registry — the direction follows the Logged column, so there is nothing to get wrong"},
			{Key: ".", Description: "Cycle sort column (Images tab only)"},
			{Key: "b (Images)", Description: "Open the multi-registry browser — search tags across all configured registries"},
			{Key: "r (Browser tags)", Description: "Cycle the active registry filter (shows tags from one registry at a time)"},
			{Key: "p (Browser)", Description: "Pull the selected image tag to the local " + engTitle + " store"},
			{Key: "S (Browser)", Description: "Scan the selected image tag directly via Trivy (no pull required)"},
			{Key: "enter (Browser tags)", Description: "View CVE details for the selected tag (only when scan results are cached)"},
			{Key: "esc (Browser)", Description: "Go back to the previous screen in the registry browser"},
			{Key: "ctrl+r", Description: "Refresh the current tab's data — on a group row, re-run member discovery"},
			{Key: "→ (Registries)", Description: "Show a group's discovered members, plus the ones declared by hand with a parent"},
			{Key: "Members (Registries)", Description: "Last discovery of a group: never (not asked yet), N · age (members listed), 0 · age (the group answered with no member), denied · age or denied · N known · age (the manager refused to list the members to this account; \"N known\" is the list from before the refusal, still used; on a narrow terminal the end is cut, so denied stays). A refused group's members can be declared by hand with repo_prefix and a parent"},
			{Key: "← (Registries)", Description: "Go back to the registry list"},
			{Key: "/", Description: "Filter images by repository or tag (Images tab only)"},
			{Key: "→ (Browser images)", Description: "Open the tags of the selected image, on its registry only"},
			{Key: "r (Browser images)", Description: "Filter the results by registry or group, cycling through them, then off"},
			{Key: "/ (Browser images)", Description: "Filter the images a registry search found, by name or description"},
			{Key: "Header (Browser images)", Description: "Below the image count, one line per kind of registry that has something to report: Pending (still searching), Interrupted (search stopped before it answered), Failed (error), Refused (does not support image search), Partial (answer cut at a cap), Cached only (Nexus group or group member: the list is limited to cached content; \"(no result)\" means nothing in the cache), No result (answered with nothing), Skipped (catalog not browsed for a one-character query). A long list ends with +N"},
			{Key: ". (Browser images)", Description: "Cycle the sort: Name, Registry, Stars (most first), each way, then the default order"},
			{Key: "esc (Browser images)", Description: "Close the filter bar, then clear the confirmed filter, then go back to the search form"},
			{Key: "↑/k", Description: "Move selection up"},
			{Key: "↓/j", Description: "Move selection down"},
			{Key: "ctrl+p", Description: "Open command mode"},
			{Key: "?", Description: "Show this help"},
		},
		Sections: []help.Section{
			indicator.Legend(),
			{
				Title: "Images Tab",
				Body: "Shows all local " + engTitle + " images with disk usage, content size, and CVE scan results.\n" +
					"Update: an arrow when the image's registry has something newer — a later patch tag on the same line (node:20.11.1 → 20.11.4), or new content behind the same tag (the arrow alone — a new build: latest, a codename, or a tag rebuilt in place). Only pulled images are asked; the registries are asked in the background when the list loads, and each answer is kept 6 hours. G updates it: it pulls the newer image and removes the one it replaces, and refuses while any container — running or stopped — uses that image, naming them in the footer. A pull done any other way clears the arrow too. Otherwise the cell says why there is none, with an icon: a check mark (up to date), an hourglass (the registry has not answered yet), a question mark in a circle (it did not answer — see the logs), a hammer (built or loaded here, never sent to a registry).\n" +
					"Sig: the signature of the content you have — the digest the image was pulled under — checked against your rules (~/.devdesk/trust.yaml) and the built-in ones, in the background when the list loads. A check mark is a proven signature; a dash, no rule covers the image (nothing is asked then); a hammer, built or loaded here, with no published signature to check; an hourglass, a check still running. A red cross is an unexpected identity, or no signature where a rule asks for one; an orange sign, a check that could not run. The column only informs: G is verified when it runs, whatever the cell says.\n" +
					"With the Misconfiguration category on, a CFG column counts what Trivy found in the Dockerfile instructions baked into the layers, coloured by the worst severity among them; a dash means no misconfiguration stage read the image, which is not a zero.\n" +
					"Press Enter to view the last scan details (loads from cache; falls back to scan if not yet scanned).\n" +
					"Press Ctrl+E to launch a container from the selected image (opens a form with pre-filled port mappings from EXPOSE metadata).\n" +
					"Press Ctrl+S to open the Security view for a configured scan.",
