	t.Helper()
	known := map[string]bool{}
	for _, f := range fixtures {
		known[f.Name] = true
		if got := s.Hits(f.Name); got != want[f.Name] {
			t.Errorf("Hits(%s) = %d, want %d", f.Name, got, want[f.Name])
		}
	}
	for name := range want {
		if !known[name] {
			t.Fatalf("the test names an unknown fixture %q", name)
		}
	}
}

