			if !slices.Equal(keys, wantKeys) {
				t.Fatalf("keys = %v, want %v", keys, wantKeys)
			}
			if len(keys) > shortcut.HeaderRows {
				t.Errorf("%d lines, want at most %d", len(keys), shortcut.HeaderRows)
